import org.jetbrains.kotlin.gradle.dsl.JvmTarget

plugins {
    kotlin("jvm") version "2.4.21"
}

repositories {
    mavenCentral()
}

val androidJar = providers.environmentVariable("ANDROID_JAR")
    .orElse("/usr/lib/android-sdk/platforms/android-23/android.jar")

sourceSets.main {
    // R.java generated by aapt.
    java.srcDir(layout.buildDirectory.dir("gen"))
    // JNI declarations shared with the main app; the C++ core is built by build-apk.sh.
    kotlin.srcDir("../app/src/main/java")
    kotlin.include("com/unigis/indoormap/lite/**", "com/unigis/indoormap/core/NativeCore.kt")
}

dependencies {
    compileOnly(files(androidJar))
}

java {
    sourceCompatibility = JavaVersion.VERSION_1_8
    targetCompatibility = JavaVersion.VERSION_1_8
}

kotlin {
    compilerOptions {
        jvmTarget.set(JvmTarget.JVM_1_8)
        // dx cannot handle invokedynamic, so lambdas must be compiled to classes.
        freeCompilerArgs.addAll(
            "-Xlambdas=class",
            "-Xsam-conversions=class",
            "-Xstring-concat=inline",
        )
    }
}

tasks.register<Copy>("copyRuntime") {
    from(configurations.runtimeClasspath)
    into(layout.buildDirectory.dir("runtime"))
}
